import { IsIn, IsISO8601, IsOptional, IsString, MaxLength } from 'class-validator';
import { JOB_STATUSES, type JobStatus } from '../job.constants.js';

/** Event types that users can record by hand; the rest are generated by the server. */
export const MANUAL_EVENT_TYPES = ['note', 'interview', 'follow_up'] as const;
export type ManualEventType = (typeof MANUAL_EVENT_TYPES)[number];

export class CreateJobEventDto {
  @IsIn(MANUAL_EVENT_TYPES)
  type!: ManualEventType;

  @IsOptional()
  @IsString()
  @MaxLength(300)
  title?: string | null;

  @IsOptional()
  @IsString()
  @MaxLength(20_000)
  body?: string | null;

  @IsOptional()
  @IsISO8601()
  occurredAt?: string;
}

/**
 * Which fields may change depends on the event: manual events take everything but `toStatus`,
 * status changes take `toStatus` and `occurredAt`, and the created event only `occurredAt`.
 */
export class UpdateJobEventDto {
  @IsOptional()
  @IsIn(MANUAL_EVENT_TYPES)
  type?: ManualEventType;

  @IsOptional()
  @IsString()
  @MaxLength(300)
  title?: string | null;

  @IsOptional()
  @IsString()
  @MaxLength(20_000)
  body?: string | null;

  @IsOptional()
  @IsISO8601()
  occurredAt?: string;

  /** The status a status change moved the job to. The previous status follows from the history. */
  @IsOptional()
  @IsIn(JOB_STATUSES)
  toStatus?: JobStatus;
}
